102	// only the built-in qemu descriptor, so it resolves that directly rather than
103	// discover_engines(), which would spawn a --describe subprocess per Verilator
104	// build only to discard them all here.
105	int run_fast(const Cli& cli) {
106	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
107	  if (!cli.engine.empty() && cli.engine != "qemu64" && cli.engine != "qemu32") {
108	    std::fprintf(stderr,
109	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
110	                 "got '%s'\n",
111	                 cli.engine.c_str());
112	    return 2;
113	  }
114	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
115	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
116	  std::string err;
117	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
118	  if (!err.empty()) {
119	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
120	    return 2;
